// ============================================================================
// STATE TRANSITIONS
// ============================================================================

/// Valid state transitions in the process mining lifecycle.
/// Defines which states can follow which other states.
pub struct StateTransitions;

impl StateTransitions {
    /// Check if transition from `from_state` to `to_state` is valid.
    pub fn is_valid(from_state: LifecycleState, to_state: LifecycleState) -> bool {
        matches!(
            (from_state, to_state),
            (LifecycleState::Created, LifecycleState::InProgress) |
            (LifecycleState::InProgress, LifecycleState::Completed) |
            (LifecycleState::InProgress, LifecycleState::Cancelled) |
            (LifecycleState::Completed, LifecycleState::Archived) |
            _ => false,
        )
    }

    /// Get all valid next states from the given state.
    pub fn valid_next_states(from_state: LifecycleState) -> Vec<LifecycleState> {
        let mut next = Vec::new();
        for candidate in &[
            LifecycleState::CREATED,
            LifecycleState::INPROGRESS,
            LifecycleState::COMPLETED,
            LifecycleState::CANCELLED,
            LifecycleState::ACTIVE,
            LifecycleState::INACTIVE,
            LifecycleState::SEEDED,
            LifecycleState::ARCHIVED,
        ] {
            if Self::is_valid(from_state, *candidate) {
                next.push(*candidate);
            }
        }
        next
    }
}

