/// An OCEL (Object-Centric Event Log) — collection of traces for process mining.
/// Event logs are validated against process models using conformance checking.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct EventLog {
    /// Collection of traces in this event log
    #[serde(default)]
    pub traces: Vec<Trace>,
}

impl EventLog {
    /// Create a new empty event log.
    pub fn new() -> Self {
        Self {
            traces: Vec::new(),
        }
    }

    /// Create an event log from the default context (empty).
    pub fn from_default() -> Self {
        Self::new()
    }

    /// Add a trace to this event log.
    pub fn with_trace(mut self, trace: Trace) -> Self {
        self.traces.push(trace);
        self
    }

    /// Add multiple traces to this event log.
    pub fn with_traces(mut self, traces: Vec<Trace>) -> Self {
        self.traces.extend(traces);
        self
    }

    /// Get a trace by index.
    pub fn get_trace(&self, index: usize) -> Option<&Trace> {
        self.traces.get(index)
    }

    /// Get all traces in this event log.
    pub fn traces(&self) -> &[Trace] {
        &self.traces
    }

    /// Get the number of traces in this event log.
    pub fn trace_count(&self) -> usize {
        self.traces.len()
    }

    /// Get the total number of events across all traces.
    pub fn total_event_count(&self) -> usize {
        self.traces.iter().map(|t| t.event_count()).sum()
    }

    /// Check if this event log is empty (no traces).
    pub fn is_empty(&self) -> bool {
        self.traces.is_empty()
    }

    /// Get the trace with the specified case id (if any).
    pub fn get_trace_by_case_id(&self, case_id: &str) -> Option<&Trace> {
        self.traces.iter().find(|t| t.case_id == case_id)
    }

    /// Get all unique event names across all traces.
    pub fn all_event_names(&self) -> Vec<&str> {
        let mut names = Vec::new();
        for trace in &self.traces {
            for event in &trace.events {
                if !names.contains(&event.name.as_str()) {
                    names.push(event.name.as_str());
                }
            }
        }
        names
    }

    /// Get all unique places across all traces.
    pub fn all_places(&self) -> Vec<&str> {
        let mut places = Vec::new();
        for trace in &self.traces {
            for place in &trace.places {
                if !places.contains(&place.as_str()) {
                    places.push(place.as_str());
                }
            }
        }
        places
    }

    /// Get statistics about this event log.
    pub fn statistics(&self) -> LogStatistics {
        LogStatistics {
            trace_count: self.trace_count(),
            event_count: self.total_event_count(),
            unique_activities: self.all_event_names().len(),
            unique_places: self.all_places().len(),
            min_trace_length: self.traces.iter().map(|t| t.event_count()).min().unwrap_or(0),
            max_trace_length: self.traces.iter().map(|t| t.event_count()).max().unwrap_or(0),
        }
    }
}

impl Default for EventLog {
    fn default() -> Self {
        Self::new()
    }
}

