/// Statistics summarizing an event log.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct LogStatistics {
    /// Total number of traces in the log
    pub trace_count: usize,
    /// Total number of events across all traces
    pub event_count: usize,
    /// Number of unique activity names
    pub unique_activities: usize,
    /// Number of unique places/stages
    pub unique_places: usize,
    /// Shortest trace length
    pub min_trace_length: usize,
    /// Longest trace length
    pub max_trace_length: usize,
}

impl LogStatistics {
    /// Get average trace length.
    pub fn average_trace_length(&self) -> f64 {
        if self.trace_count == 0 {
            0.0
        } else {
            self.event_count as f64 / self.trace_count as f64
        }
    }
}

impl std::fmt::Display for LogStatistics {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(
            f,
            "EventLog: {} traces, {} events, {} activities, {} places (trace length: {}-{})",
            self.trace_count,
            self.event_count,
            self.unique_activities,
            self.unique_places,
            self.min_trace_length,
            self.max_trace_length
        )
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_lifecycle_from_str() {
        assert_eq!(LifecycleState::from_str("created"), Some(LifecycleState::CREATED));
        assert_eq!(LifecycleState::from_str("unknown"), None);
    }

    #[test]
    fn test_attribute_creation() {
        let attr = Attribute::new("test_key", "test_value");
        assert_eq!(attr.key, "test_key");
        assert_eq!(attr.value, "test_value");
        assert!(!attr.has_attributes());
    }

    #[test]
    fn test_event_creation() {
        let now = Utc::now();
        let event = Event::new("evt1", "start", LifecycleState::SEEDED, now);
        assert_eq!(event.id, "evt1");
        assert_eq!(event.name, "start");
        assert_eq!(event.lifecycle, LifecycleState::SEEDED);
        assert!(!event.has_attributes());
    }

    #[test]
    fn test_trace_creation() {
        let trace = Trace::new("case1");
        assert_eq!(trace.case_id, "case1");
        assert!(trace.is_empty());
    }

    #[test]
    fn test_event_log_creation() {
        let log = EventLog::new();
        assert!(log.is_empty());
        assert_eq!(log.trace_count(), 0);
    }

    #[test]
    fn test_event_log_with_trace() {
        let trace = Trace::new("case1");
        let log = EventLog::new().with_trace(trace);
        assert_eq!(log.trace_count(), 1);
    }
}